import{_ as n,o as s,c as o,ag as r,j as d}from"./chunks/framework.KxDd3USm.js";const u=JSON.parse('{"title":"07.2 编译的六个阶段 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"07-程序设计语言基础/02-编译阶段.md","filePath":"07-程序设计语言基础/02-编译阶段.md"}'),e={name:"07-程序设计语言基础/02-编译阶段.md"},g={class:"fig"},a={"data-figure-id":"figure-28",viewBox:"0 0 720 170",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"编译六阶段流水线，从源程序字符流经过词法分析得到记号流，语法分析得到语法树，语义分析后生成中间代码，再经优化生成目标程序。符号表贯穿语义分析和后续阶段。"};function i(l,t,x,h,p,_){return s(),o("div",null,[t[2]||(t[2]=r('<h1 id="_07-2-编译的六个阶段-★★★" tabindex="-1">07.2 编译的六个阶段 ★★★ <a class="header-anchor" href="#_07-2-编译的六个阶段-★★★" aria-label="Permalink to &quot;07.2 编译的六个阶段 ★★★&quot;">​</a></h1><p><strong>动机</strong>：为什么翻译不一步到位，要分六个阶段？因为&quot;读懂一段话&quot;本身就是分层的：先认字（词法），再看句子通不通（语法），再理解意思对不对（语义），最后才落笔翻译（中间代码→优化→目标代码）。分层后每个阶段只管一件事，出错也好定位——你在第 2 阶段就发现&quot;句子结构不对&quot;，不必等到最后生成机器码才发现。</p><table tabindex="0"><thead><tr><th>阶段</th><th>输入 → 输出</th><th>干什么</th><th>依据/工具</th><th>理论考点</th></tr></thead><tbody><tr><td>① <strong>词法分析</strong></td><td>源程序字符流 → <strong>记号流</strong>（单词符号序列）</td><td>从左到右逐个扫描字符，识别出关键字、标识符、常数、运算符、分隔符</td><td>正规式、<strong>有限自动机</strong></td><td>词法错误</td></tr><tr><td>② <strong>语法分析</strong></td><td>记号流 → <strong>语法树</strong></td><td>按语法规则把单词组成语法单位，检查结构合法性（如 if…end if 配对、括号匹配）</td><td><strong>自顶向下</strong>：递归下降、预测分析；<strong>自底向上</strong>：移进-归约</td><td>语法错误</td></tr><tr><td>③ <strong>语义分析</strong></td><td>语法树</td><td>类型检查等<strong>静态语义</strong>检查（如对浮点数做取余、运算对象类型不合法）</td><td><strong>符号表</strong>辅助</td><td>静态语义错误</td></tr><tr><td>④ <strong>中间代码生成</strong></td><td>语义分析结果 → 中间代码</td><td>生成与<strong>具体机器无关</strong>的中间形式</td><td>常用形式：<strong>后缀式、语法树、三地址码、四元式</strong></td><td>四元式 (运算符， 对象1， 对象2， 结果)</td></tr><tr><td>⑤ <strong>代码优化</strong></td><td>中间代码 → 更优的中间代码</td><td>提高效率（删冗余、提公共子表达式等）</td><td>—</td><td>—</td></tr><tr><td>⑥ <strong>目标代码生成</strong></td><td>中间代码 → <strong>目标程序</strong></td><td>转成低级语言代码，<strong>与硬件系统结构密切相关</strong>（寄存器分配等）</td><td>—</td><td>—</td></tr></tbody></table><p>六阶段不是每个编译器都必须逐项拥有：<strong>词法、语法、语义分析和目标代码生成是基本阶段；中间代码生成与代码优化可以省略</strong>。省略优化只会使目标程序可能不够快，不代表不能正确运行。</p><p>目标程序常见三种形式：</p><ul><li><strong>绝对指令代码</strong>：地址已经确定，可直接装入固定位置执行；</li><li><strong>可重定位指令代码</strong>：地址尚可调整，装入或链接时再确定实际位置；</li><li><strong>汇编指令代码</strong>：还需汇编程序进一步翻译成机器指令。</li></ul><p><strong>反例演示（易错）</strong>：“代码优化是必需阶段”错误；优化服务于效率，不决定源程序语义是否正确。“汇编代码属于中间代码”也错误，教材把它列作目标代码形式之一；常见中间代码是后缀式、语法树、三地址码和四元式。</p><p><strong>顺序口诀</strong>：<strong>词法 → 语法 → 语义 → 中间 → 优化 → 目标</strong>（&quot;认字 → 组句 → 懂意 → 打草稿 → 改稿 → 定稿&quot;）。另外<strong>符号表</strong>贯穿编译全程，记录各符号（变量、函数）的信息，辅助语义检查和代码生成。</p>',8)),d("figure",g,[(s(),o("svg",a,[...t[0]||(t[0]=[r('<defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><text x="20" y="35" class="s">源程序</text><g class="b"><rect x="80" y="15" width="82" height="42" rx="10"></rect><rect x="190" y="15" width="82" height="42" rx="10"></rect><rect x="300" y="15" width="82" height="42" rx="10"></rect><rect x="410" y="15" width="82" height="42" rx="10"></rect><rect x="520" y="15" width="82" height="42" rx="10"></rect><rect x="630" y="15" width="82" height="42" rx="10"></rect></g><g class="t"><text x="96" y="42">词法</text><text x="206" y="42">语法</text><text x="316" y="42">语义</text><text x="426" y="42">中间</text><text x="536" y="42">优化</text><text x="646" y="42">目标</text></g><path d="M62 36H79M162 36H189M272 36H299M382 36H409M492 36H519M602 36H629" class="e" marker-end="url(#a)"></path><text x="95" y="80" class="s">记号流</text><text x="198" y="80" class="s">语法树</text><text x="388" y="80" class="s">中间代码</text><text x="628" y="80" class="s">目标程序</text><rect x="290" y="112" width="250" height="34" rx="8" fill="var(--gold-soft)" stroke="var(--gold)" stroke-width="2"></rect><text x="374" y="134" class="t">符号表贯穿全程</text>',11)])])),t[1]||(t[1]=d("figcaption",null,"前端负责读懂源程序，后端负责面向具体机器生成代码；优化可省略，基本正确性不受影响。",-1))]),t[3]||(t[3]=r(`<p><strong>中间代码举例</strong>（四元式）：对 <code>x := y + z * 60</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(*, z, 60, t1)   ← 先算乘法，结果放临时变量 t1</span></span>
<span class="line"><span>(+, y, t1, t2)   ← 再算加法</span></span>
<span class="line"><span>(:=, t2,  , x)   ← 赋值</span></span></code></pre></div><p>中间代码&quot;中间&quot;的意义：它站在高级语言和机器语言之间，<strong>与机器无关</strong>——前端（词法/语法/语义）只管&quot;读懂&quot;，产出到中间代码为止；后端（优化/目标代码）才管&quot;搬到具体机器上&quot;。换一种 CPU，前端原封不动，只改后端。</p><p><strong>错误分类（必考表格，背熟）</strong>：</p><table tabindex="0"><thead><tr><th>类别</th><th>发现时机</th><th>例子</th></tr></thead><tbody><tr><td><strong>词法错误</strong></td><td>编译时（词法分析阶段）</td><td>使用了语言字符集以外的非法字符、单词拼写错误、标点符号错误（如误用中文标点）</td></tr><tr><td><strong>语法错误</strong></td><td>编译时（语法分析阶段）</td><td>括号不匹配、缺少分号、if…end if 不配对、<strong>表达式中缺少操作数</strong></td></tr><tr><td><strong>静态语义错误</strong></td><td>编译时（语义分析阶段）</td><td>运算符与运算对象<strong>类型不合法</strong>（如对浮点数做取余、整型与字符串相加）</td></tr><tr><td><strong>动态语义错误</strong></td><td><strong>运行时</strong></td><td>除数为零、数组下标越界、陷入死循环、无效指针引用</td></tr></tbody></table><p><strong>反例演示（最易混的两组）</strong>：①「拼写错误 vs 缺分号」——单词拼错、用了中文标点属于<strong>词法</strong>错误；缺分号、缺括号、缺操作数属于<strong>语法</strong>错误（涉及语言结构）。②「编译时 vs 运行时」——除零、下标越界编译器查不出来（它不知道运行时下标是多少），所以叫<strong>动态</strong>错误；死循环也是运行时才暴露。</p><p><strong>应试动作</strong>：① 背死六阶段顺序和三个&quot;输入→输出&quot;（字符流→记号流→语法树→中间代码→目标程序）；② 错误四分类给例子能归类——判断窍门先问&quot;编译时能发现吗&quot;，再按词法（字符级）/语法（结构级）/静态语义（类型级）定位；③ 记住自顶向下=递归下降/预测分析，自底向上=移进-归约。</p>`,7))])}const y=n(e,[["render",i]]);export{u as __pageData,y as default};
